def handle_pre_vote(node, candidate_term: int, last_log_idx: int, last_log_term: int) -> bool:
    # Reject PreVote if we heard from a valid leader within election_timeout
    if node.time_since_leader_heartbeat_ms() < node.election_timeout_ms:
        return False
    if candidate_term < node.current_term:
        return False
    return (last_log_term, last_log_idx) >= (node.last_log_term, node.last_log_idx)

